<template>
  <section class="order-document-info">
    <h3>金额信息</h3><el-alert :type="checkTone(doc.check_state)" :title="checkLabel(doc.check_state)" :description="checkDescription" :closable="false" show-icon/>
    <el-descriptions border :column="3" size="small" class="document-values"><el-descriptions-item v-for="item in amounts" :key="item[0]" :label="item[0]">{{ money(doc[item[1]]) }}</el-descriptions-item><el-descriptions-item label="币种">{{ doc.currency || '未提供' }}</el-descriptions-item></el-descriptions>
    <p class="help">优惠合计＝商品自身优惠合计＋整单优惠；子单的整单优惠分摊不重复累加。买家运费按平台邮费保存。</p>
    <ul v-if="doc.issues && doc.issues.length" class="document-issues"><li v-for="(issue,i) in doc.issues" :key="i">{{ issue }}</li></ul>
    <ul v-if="doc.differences && doc.differences.length" class="document-issues"><li v-for="(item,i) in doc.differences" :key="i">{{ item }}</li></ul>
    <el-collapse><el-collapse-item title="优惠明细与金额核对" name="money">
      <el-descriptions border :column="2" size="small"><el-descriptions-item label="按商品、优惠、改价及运费计算">{{ money(doc.calculated_payable) }}</el-descriptions-item><el-descriptions-item label="与订单实付差额">{{ money(doc.payment_difference) }}</el-descriptions-item><el-descriptions-item label="子单商品实付＋运费差额">{{ money(doc.line_difference) }}</el-descriptions-item><el-descriptions-item label="平台分摊合计差额">{{ money(doc.platform_divided_difference) }}</el-descriptions-item><el-descriptions-item label="整单优惠分摊差额">{{ money(doc.discount_share_difference) }}</el-descriptions-item></el-descriptions>
      <p class="help">订单差额按订单金额减明细计算；子单差额按销售及优惠计算值减平台商品实付计算。平台应付保留原值，优惠明细仅供核对，不再次汇总到优惠合计。</p>
      <el-table :data="doc.promotions || []" size="small" empty-text="平台未提供优惠明细"><el-table-column label="优惠名称" min-width="180"><template slot-scope="s">{{ s.row.promotion_name || s.row.promotion_desc || '未提供' }}</template></el-table-column><el-table-column label="关联订单号" prop="id" min-width="180"/><el-table-column label="优惠金额" width="120" align="right"><template slot-scope="s">{{ money(s.row.amount) }}</template></el-table-column><el-table-column label="承担方" width="100"><template>未提供</template></el-table-column></el-table>
    </el-collapse-item></el-collapse>
    <template v-if="business"><h3>退款金额</h3><el-descriptions border :column="2" size="small"><el-descriptions-item label="退款申请中">{{ money((order.refund_amounts || {}).pending) }}</el-descriptions-item><el-descriptions-item label="平台确认退款成功">{{ money((order.refund_amounts || {}).succeeded) }}</el-descriptions-item></el-descriptions><p class="help">退款单金额单独汇总，原订单销售金额与实付保持原值；退款商品及处理进度见“退款与换货”。退款中的商品、运费拆分未提供时不推算。</p></template>
    <h3>交易资料</h3><el-descriptions border :column="2" size="small"><el-descriptions-item v-for="item in metadata" :key="item[0]" :label="item[0]">{{ doc[item[1]] || '未提供' }}</el-descriptions-item><el-descriptions-item label="买家留言" :span="2"><span class="document-note">{{ doc.buyer_message || '未提供' }}</span></el-descriptions-item><el-descriptions-item label="平台卖家备注" :span="2"><span class="document-note">{{ doc.seller_memo || '未提供' }}</span></el-descriptions-item></el-descriptions>
    <template v-if="business"><h3>OMS 内部备注</h3><div v-hasPermi="['order:order:update']" class="internal-note-form"><el-input v-model="note" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="填写内部处理说明，与平台备注分别保存"/><el-button type="primary" size="small" :loading="saving" :disabled="!note.trim()" @click="saveNote">添加备注</el-button></div><el-table :data="order.internal_notes || []" size="small" empty-text="暂无内部备注（显示最近20条）"><el-table-column label="备注内容" min-width="260"><template slot-scope="s"><span class="document-note">{{ s.row.message }}</span></template></el-table-column><el-table-column label="操作人" prop="operator_name" width="120"/><el-table-column label="时间" prop="create_time" width="170"/></el-table></template>
    <el-collapse><el-collapse-item title="发票资料" name="invoice"><el-descriptions border :column="2" size="small"><el-descriptions-item v-for="item in invoice" :key="item[0]" :label="item[0]">{{ doc[item[1]] || '未提供' }}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse>
  </section>
</template>
<script>
import { documentOf, money, checkLabel, checkTone } from './orderAmounts'
import { addOrderNote } from '@/api/order'
export default {
  name: 'OrderDocumentInfo', props: { order: { type: Object, required: true }, business: Boolean },
  data: () => ({ note: '', saving: false, amounts: [['商品销售总额', 'sales_amount'], ['优惠合计', 'discount_total'], ['买家运费', 'buyer_freight'], ['商品自身优惠合计', 'item_discount'], ['整单优惠', 'order_discount'], ['子单改价合计', 'adjustment'], ['商品实付合计（不含运费）', 'goods_payment'], ['订单实付（含运费）', 'payment'], ['平台应付金额', 'platform_payable']], metadata: [['平台下单时间', 'created'], ['平台付款时间', 'pay_time'], ['平台发货时间', 'consign_time'], ['平台交易结束时间', 'end_time'], ['金额来源版本时间', 'source_modified'], ['交易资料更新时间', 'metadata_modified']], invoice: [['发票抬头', 'invoice_name'], ['发票类型', 'invoice_type'], ['发票税号', 'invoice_tax_no'], ['开票状态', 'invoice_status']] }),
  computed: { doc() { return documentOf(this.order) }, checkDescription() { return this.doc.check_state === 'MATCHED' ? '商品金额、优惠、运费与订单实付核对一致，整单优惠分摊一致。' : this.doc.check_state === 'DIFFERENCE' ? '存在可计算的金额差额，展开核对结果查看具体金额；原始平台金额保留。' : '缺少或无效的金额保持未提供；不自动补零。资料完整后再核对。' } }, watch: { 'order.id'() { this.note = '' } }, methods: { money, checkLabel, checkTone, async saveNote() { if (this.saving || !this.note.trim()) return; this.saving = true; try { await addOrderNote(this.order.id, this.note.trim()); this.note = ''; this.$message.success('内部备注已保存'); this.$emit('changed') } finally { this.saving = false } } }
}
</script>
<style scoped>.internal-note-form{display:flex;align-items:flex-end;gap:12px;margin-bottom:14px}.order-document-info h3{font-size:16px;margin:22px 0 14px;color:#34445a}.document-values{margin-top:14px}.help{color:#7a8798;font-size:12px;line-height:1.8}.document-note{white-space:pre-wrap;overflow-wrap:anywhere}.document-issues{color:#b88230;line-height:1.8}.order-document-info ::v-deep .el-descriptions-item__content{overflow-wrap:anywhere;font-variant-numeric:tabular-nums}</style>
